        $errors = array_map(
            static fn (array $error): string => sprintf('[%s] %s%s', $error['property'], $error['message'], PHP_EOL),
            $validator->getErrors(),
        );

        throw InvalidSchema::create($rawConfig, $errors);
    }
}
